package server

// Authorization policies for the spectasks routes. See route_auth_policy_test.go
// for the classes; routePolicyFile says which file a new route belongs in.
func init() {
	declareRoutePolicies(map[string]routePolicy{
		"POST /api/v1/spec-tasks/from-prompt":                                                             object("createTaskFromPromptWithMaxRequestBytes"),
		"GET /api/v1/spec-tasks":                                                                          object("authorizeOrgMember", "authorizeUserToProjectByID"),
		"GET /api/v1/spec-tasks/board-settings":                                                           object("loadBoardSettingsProject"),
		"PUT /api/v1/spec-tasks/board-settings":                                                           object("loadBoardSettingsProject"),
		"GET /api/v1/spec-tasks/{taskId}":                                                                 object("authorizeUserToProjectByID"),
		"POST /api/v1/spec-tasks/{taskId}/refresh-pull-request":                                           object("authorizeUserToProjectByID"),
		"PUT /api/v1/spec-tasks/{taskId}":                                                                 object("authorizeUserToProjectByID"),
		"GET /api/v1/spec-tasks/{taskId}/execution-config":                                                object("authorizeUserToProjectByID"),
		"PATCH /api/v1/spec-tasks/{taskId}/execution-config":                                              object("authorizeUserToProjectByID"),
		"GET /api/v1/spec-tasks/{taskId}/interactive-embed-model":                                         object("loadInteractiveEmbedModelTask"),
		"PATCH /api/v1/spec-tasks/{taskId}/interactive-embed-model":                                       object("loadInteractiveEmbedModelTask"),
		"DELETE /api/v1/spec-tasks/{taskId}":                                                              object("authorizeUserToProjectByID"),
		"PATCH /api/v1/spec-tasks/{taskId}/archive":                                                       object("authorizeUserToProjectByID"),
		"GET /api/v1/spec-tasks/{taskId}/specs":                                                           object("authorizeUserToProjectByID"),
		"GET /api/v1/spec-tasks/{taskId}/progress":                                                        object("authorizeUserToProjectByID"),
		"POST /api/v1/spec-tasks/{taskId}/start-planning":                                                 object("authorizeUserToProjectByID"),
		"POST /api/v1/spec-tasks/{taskId}/approve-specs":                                                  object("authorizeUserToProjectByID"),
		"POST /api/v1/spec-tasks/{taskId}/clone":                                                          object("authorizeQuickCreateProject", "authorizeUserToProjectByID"),
		"GET /api/v1/spec-tasks/{taskId}/clone-groups":                                                    object("authorizeUserToProjectByID"),
		"POST /api/v1/spec-tasks/{taskId}/labels":                                                         object("authorizeUserToProjectByID"),
		"DELETE /api/v1/spec-tasks/{taskId}/labels/{label}":                                               object("authorizeUserToProjectByID"),
		"POST /api/v1/spec-tasks/{taskId}/attachments":                                                    object("authorizeUserToProjectByID"),
		"GET /api/v1/spec-tasks/{taskId}/attachments":                                                     object("authorizeUserToProjectByID"),
		"DELETE /api/v1/spec-tasks/{taskId}/attachments/{attId}":                                          object("authorizeUserToProjectByID"),
		"GET /api/v1/spec-tasks/{id}/usage":                                                               object("authorizeUserToProjectByID"),
		"GET /api/v1/clone-groups/{groupId}/progress":                                                     object("authorizeUserToProjectByID"),
		"POST /api/v1/spec-tasks/{spec_task_id}/approve-implementation":                                   object("authorizeUserToProject"),
		"GET /api/v1/spec-tasks/{spec_task_id}/pr-proposals":                                              object("authorizedSpecTaskForProposals"),
		"POST /api/v1/spec-tasks/{spec_task_id}/pr-proposals/{proposal_id}/decide":                        object("authorizedSpecTaskForProposals"),
		"POST /api/v1/spec-tasks/{spec_task_id}/completion/decide":                                        object("authorizedSpecTaskForProposals"),
		"POST /api/v1/spec-tasks/{spec_task_id}/stop-agent":                                               object("authorizeUserToProject"),
		"GET /api/v1/spec-tasks/{spec_task_id}/design-reviews":                                            object("authorizeUserToProjectByID"),
		"GET /api/v1/spec-tasks/{spec_task_id}/design-reviews/{review_id}":                                object("authorizeUserToProjectByID"),
		"PUT /api/v1/spec-tasks/{spec_task_id}/design-reviews/{review_id}/document":                       object("authorizeUserToProjectByID"),
		"POST /api/v1/spec-tasks/{spec_task_id}/design-reviews/{review_id}/submit":                        object("authorizeUserToProjectByID"),
		"POST /api/v1/spec-tasks/{spec_task_id}/design-reviews/{review_id}/comments":                      object("authorizeUserToProjectByID"),
		"GET /api/v1/spec-tasks/{spec_task_id}/design-reviews/{review_id}/comments":                       object("authorizeUserToProjectByID"),
		"POST /api/v1/spec-tasks/{spec_task_id}/design-reviews/{review_id}/comments/{comment_id}/resolve": object("authorizeUserToProjectByID"),
		"GET /api/v1/spec-tasks/{spec_task_id}/design-reviews/{review_id}/comment-queue-status":           object("authorizeUserToProjectByID"),
		"GET /api/v1/spec-tasks/{taskId}/zed-instance":                                                    object("authorizeUserToZedSpecTask"),
		"DELETE /api/v1/spec-tasks/{taskId}/zed-instance":                                                 object("authorizeUserToZedSpecTask"),
		"GET /api/v1/spec-tasks/{taskId}/zed-threads":                                                     object("authorizeUserToProjectByID"),
		"GET /api/v1/specs/sample-types":                                                                  user(),
		"GET /api/v1/spec-tasks/{id}/view":                                                                public("design docs of a task whose owner set PublicDesignDocs; 404 otherwise"),
		"GET /api/v1/spec-tasks/{taskId}/attachments/{attId}/content":                                     handlerAuth("public when the task has PublicDesignDocs, otherwise the caller must be authorized to the project").authz("authorizeUserToProjectByID"),
	})
}
